#include <esp_now.h>
#include <WiFi.h>

uint8_t receiverMAC[] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};

esp_now_peer_info_t peerInfo;

#define CMD_LED_ON 1
#define CMD_LED_OFF 0
int sw[] = {13, 12, 14, 27, 26, 25, 33, 32};
int ledState = 0;

void onSendDone(const uint8_t *mac, esp_now_send_status_t status)
{
    Serial.print("Send: ");
    Serial.println(status == ESP_NOW_SEND_SUCCESS ? "OK" : "FAIL");
}

void setup()
{
    Serial.begin(115200);
    pinMode(2, OUTPUT);
    for (int i = 0; i < 8; i++)
    {
        pinMode(sw[i], INPUT_PULLUP);
    }

    WiFi.mode(WIFI_STA);
    Serial.print("Sender MAC: ");
    Serial.println(WiFi.macAddress());

    esp_now_init();
    esp_now_register_send_cb(onSendDone);

    memcpy(peerInfo.peer_addr, receiverMAC, 6);
    peerInfo.channel = 0;
    peerInfo.encrypt = false;
    esp_now_add_peer(&peerInfo);
    Serial.println("Sender ready — waiting 3s for receiver...");
    delay(3000);
}

void loop()
{
    uint8_t sw_data = 0;

for (int i = 0; i < 8; i++) {
    if (digitalRead(sw[i]) == HIGH) {
        sw_data |= (1 << i); // Sets bit 'i' to 1
    }
}
    esp_now_send(receiverMAC, (uint8_t *)&sw_data, sizeof(sw_data));
    Serial.print("Sent: ");
    Serial.println(sw_data ? "LED_ON" : "LED_OFF");
    delay(2000);
}

