#include <esp_now.h>
#include <WiFi.h>

#define RECEIVER_LED_PIN 2
#define CMD_LED_ON 1
#define CMD_LED_OFF 0

int Leds[] = {15, 2, 4, 16, 17, 5, 18, 19};

typedef struct
{
    int command;
} ControlPacket;
// received_data is the 8-bit byte (uint8_t) sent from the transmitter
void updateLEDs(uint8_t received_data)
{
    for (int i = 0; i < 8; i++)
    {
        // Extract bit 'i' (0 or 1) and write to LED 'i'
        int state = bitRead(received_data, i);
        digitalWrite(Leds[i], state);
    }
}
ControlPacket incomingData;

// Dual core version support for receive callback
#if defined(ESP_ARDUINO_VERSION_MAJOR) && ESP_ARDUINO_VERSION_MAJOR >= 3
void onRecvData(const esp_now_recv_info_t *info, const uint8_t *data, int len)
{
#else
void onRecvData(const uint8_t *mac, const uint8_t *data, int len)
{
#endif
    // Validate incoming packet size before processing
    if (len == sizeof(ControlPacket))
    {
        memcpy(&incomingData, data, sizeof(incomingData));
        updateLEDs(incomingData.command);
    }
    else
    {
        Serial.println("Warning: Invalid packet size received!");
    }
}

void setup()
{
    Serial.begin(115200);
    pinMode(RECEIVER_LED_PIN, OUTPUT);
    digitalWrite(RECEIVER_LED_PIN, LOW);

    WiFi.mode(WIFI_STA);
    Serial.print("Receiver MAC: ");
    Serial.println(WiFi.macAddress());

    if (esp_now_init() != ESP_OK)
    {
        Serial.println("Error initializing ESP-NOW");
        return;
    }

    esp_now_register_recv_cb(onRecvData);
    Serial.println("Receiver ready — waiting for commands...");
}

void loop()
{
    // Free loop; processing handled asynchronously via callbacks
}
